// @input: cmd <<'CMD'
agent-browser --cdp "$AGENT_BROWSER_CDP" eval --stdin <<'JS'
(async()=>{
 const f=window.fetch;
 let turnDone;
 const turnPromise=new Promise(r=>turnDone=r);
 window.fetch=async(...args)=>{const res=await f(...args);if(String(args[0])==='/api/turn')void res.clone().text().then(turnDone);return res;};
 const input=document.querySelector('#story-idea');
 Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(input,'The tortoise puts on a shiny yellow helmet beside his roller skates.');
 input.dispatchEvent(new Event('input',{bubbles:true}));
 document.querySelector('.interaction-bar form').requestSubmit();
 const raw=await turnPromise;
 const final=raw.split('\n').filter(Boolean).map(l=>JSON.parse(l)).find(e=>e.type==='turn');
 const saveResult=new Promise(resolve=>{
  const observer=new MutationObserver(()=>{const notice=document.querySelector('.notice')?.textContent;if(notice){observer.disconnect();clearTimeout(timeout);resolve(notice);}});
  observer.observe(document.body,{childList:true,subtree:true,characterData:true});
  const timeout=setTimeout(()=>{observer.disconnect();resolve({timeout:true,error:document.querySelector('.error')?.textContent});},30000);
 });
 [...document.querySelectorAll('button')].find(b=>b.textContent.includes('Save this version')).click();
 return {segments:final?.turn.segments,scene:final?.turn.imagePrompt,save:await saveResult,images:window.__bench.images,error:document.querySelector('.error')?.textContent};
})()
