1→@import "tailwindcss";
2→
3→:root { --paper:#fbf9f3; --ink:#293e34; --green:#355b45; --muted:#62665b; --line:#e4e5d9; --orange:#bd704f; }
4→* { box-sizing:border-box; }
5→html { scroll-behavior:smooth; }
6→body { margin:0; background:var(--paper); color:var(--ink); font-family:Arial,Helvetica,sans-serif; font-size:15px; -webkit-font-smoothing:antialiased; }
7→button,input { font:inherit; }
8→button,a { -webkit-tap-highlight-color:transparent; }
9→a { color:inherit; text-decoration:none; }
10→button { cursor:pointer; }
11→button:disabled { opacity:.48; cursor:not-allowed; }
12→button { color:inherit; }
13→button,a,input { outline-offset:5px; }
14→:focus-visible { outline:2px solid var(--orange); }
15→h1,h2,h3,p { margin:0; }
16→h1,h2,h3,.brand { font-family:Georgia,'Times New Roman',serif; font-weight:400; }
17→h1 { font-size:clamp(36px,4.5vw,63px); line-height:1.12; letter-spacing:-2.3px; }
18→h1 em { color:var(--green); font-weight:400; }
19→h2 { font-size:34px; line-height:1.18; letter-spacing:-.9px; }
20→h3 { font-size:23px; line-height:1.2; letter-spacing:-.5px; }
21→.nav { max-width:1320px; margin:auto; padding:27px 60px; display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid var(--line); }
22→.brand { font-size:31px; letter-spacing:-1.5px; font-weight:600; white-space:nowrap; }
23→.brand-mark { display:inline-block; font-size:32px; color:var(--orange); margin-right:5px; }
24→.brand-dot { color:var(--orange); }
25→.nav nav { display:flex; gap:35px; align-items:center; font-size:13px; font-weight:500; }
26→.nav nav a { padding:10px 0; }
27→.nav nav a.active { color:var(--green); box-shadow:0 2px var(--green); }
28→.nav nav .nav-create { background:#e8eddf; padding:12px 19px; border-radius:7px; }
29→.library { max-width:1320px; margin:auto; padding:0 60px; }
30→.hero { display:grid; grid-template-columns:1.18fr 1fr; align-items:center; gap:40px; min-height:500px; padding:60px 0 56px; }
31→.eyebrow { font-size:10px; font-weight:600; letter-spacing:2px; color:var(--green); margin-bottom:21px; }
32→.eyebrow>span { width:6px; height:6px; background:var(--orange); display:inline-block; margin-right:7px; border-radius:50%; vertical-align:1px; }
33→.hero-description { margin:23px 0 29px; font-size:14px; line-height:1.9; color:#72776b; }
34→.button { border:1px solid transparent; border-radius:7px; padding:15px 21px; display:inline-flex; align-items:center; justify-content:center; gap:23px; font-size:13px; font-weight:500; min-height:47px; transition:transform .2s,background .2s; }
35→.button:hover:not(:disabled) { transform:translateY(-2px); }

