      "import": "./dist/index.mjs",
      "require": "./dist/index.js"
    }
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "dependencies": {
    "@alloc/quick-lru": "^5.2.0",
    "@tailwindcss/node": "4.3.3",
