+"use client";
+import { useState } from "react";
+import BlobImage from "./BlobImage";
+import Scene from "./Scene";
+import styles from "./StoryPicture.module.css";
+
+export default function StoryPicture({ image, alt, kind }: { image?: Blob; alt: string; kind: string }) {
+  const [paused, setPaused] = useState(false);
+  return <>
+    <div className={styles.frame} data-motion-paused={paused}>
+      <div className={styles.artwork}>
+        {image ? <BlobImage blob={image} alt={alt}/> : <Scene kind={kind}/>}
+      </div>
+      <div className={styles.light} aria-hidden="true"/>
+    </div>
+    <button className={styles.toggle} type="button" aria-pressed={paused} onClick={() => setPaused(!paused)}>
+      {paused ? "Resume motion" : "Pause motion"}
+    </button>
+  </>;
+}
*** Add File: /Users/rizelscarlett/Documents/agent-experiments/voice-experiments/interactive-storybook/components/StoryPicture.module.css
+.frame {
+  position: absolute;
+  inset: 0;
+  overflow: hidden;
+  pointer-events: none;
+}
+
+.artwork {
+  width: 100%;
+  height: 100%;
+  animation: drift 20s ease-in-out infinite alternate;
+}
+
+.artwork > svg,
+.artwork > img {
+  width: 100%;
+  height: 100%;
+  object-fit: cover;
+}
+
+.light {
+  position: absolute;
+  inset: -10%;
+  background: radial-gradient(ellipse at 20% 20%, #fff3cf24, transparent 65%);
+  animation: light-drift 14s ease-in-out infinite alternate;
+}
+
+.frame[data-motion-paused="true"] > * {
+  animation-play-state: paused;
+}
+
+.toggle {
+  position: absolute;
+  top: 14px;
+  right: 14px;
+  border: 1px solid #dce1d0;
+  border-radius: 20px;
+  background: #fffdf6ed;
+  padding: 10px 14px;
+  min-height: 44px;
+  font-size: 11px;
+}
+
+@keyframes drift {
+  from { transform: scale(1.055) translate(-.8%, .3%); }
+  to { transform: scale(1.12) translate(.8%, -.3%); }
+}
+
+@keyframes light-drift {
+  from { transform: translate(-3%, -2%); opacity: .45; }
+  to { transform: translate(3%, 2%); opacity: .85; }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  .artwork,
+  .light { animation: none; }
+  .light,
+  .toggle { display: none; }
+}
*** End Patch

