(async () => {
  const start = performance.now();
  const res = await fetch("/api/tts", {method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({text:"Give the tortoise roller skates.",voice:"flux-hannah-en"})});
  if (!res.ok) throw new Error("TTS status " + res.status);
  const reader = res.body.getReader();
  const first = await reader.read();
  const firstByteMs = Math.round(performance.now() - start);
  const chunks = [first.value];
  for (;;) { const {done,value} = await reader.read(); if (done) break; chunks.push(value); }
  const blob = new Blob(chunks, {type:"audio/mpeg"});
  const ctx = new AudioContext();
  const buffer = await ctx.decodeAudioData(await blob.arrayBuffer());
  const dest = ctx.createMediaStreamDestination();
  window.fluxCheck = {ctx, buffer, dest, events:[], urls:[]};
  navigator.mediaDevices.getUserMedia = async () => dest.stream;
  const Original = window.WebSocket;
  window.WebSocket = class extends Original {
    constructor(url, protocols) {
      super(url, protocols);
      if (String(url).includes("deepgram.com")) {
        window.fluxCheck.urls.push(String(url));
        this.addEventListener("message", event => {
          const m = JSON.parse(event.data);
          window.fluxCheck.events.push({type:m.type,event:m.event,transcript:m.transcript,description:m.description});
        });
      }
    }
  };
  return {status:res.status,firstByteMs,mp3Bytes:blob.size,decodedSeconds:buffer.duration};
})()
